            en: "<span>🌌 50 New Beyondverse Stages (Worlds 11–15)</span><span>⚡ Phase Dash &amp; 💥 Ground Slam</span><span>⏱️ Chrono-Brake &amp; 🤖 Mini-Drone Companion</span><span>💎 Secret Relic Chests &amp; 5 New Bosses</span>",
