            ru: "<span>🌌 50 новых уровней (Миры 11–15)</span><span>⚡ Фазовый рывок и 💥 Удар о землю</span><span>⏱️ Замедление времени и 🤖 Мини-дрон</span><span>💎 Сундуки реликвий и 5 новых боссов</span>",
